public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int L = fs.nextInt();
        int C = fs.nextInt();
        int m = C - 1;

        int[] prev = new int[C];
        for (int j = 0; j < C; j++) prev[j] = fs.nextInt();

        int[] curr = new int[C];
        int[] heights = new int[m];
        int[] stack = new int[m + 1];

        int ans = Math.max(L, C);

        for (int i = 1; i < L; i++) {
            for (int j = 0; j < C; j++) curr[j] = fs.nextInt();

            for (int j = 0; j < m; j++) {
                if (prev[j] + curr[j + 1] > prev[j + 1] + curr[j]) {
                    heights[j] = 0;
                } else {
                    heights[j]++;
                }
            }

            int top = -1;
            for (int j = 0; j <= m; j++) {
                int curH = (j == m) ? -1 : heights[j];
                while (top >= 0 && heights[stack[top]] > curH) {
                    int h = heights[stack[top--]];
                    int left = (top >= 0) ? stack[top] : -1;
                    int right = j;
                    int width = right - left - 1;
                    int area = (h + 1) * (width + 1);
                    if (area > ans) ans = area;
                }
                if (j < m) stack[++top] = j;
            }

            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
